/* CodeQuest: local-first, free learning RPG. Curriculum content is a growing open-source work. */
const LANGS=[
["Python","PY","Automation, data, APIs and backend foundations."],["HTML","HT","Semantic, accessible document structure."],["CSS","CS","Layout, responsive design and visual systems."],["JavaScript","JS","Interactive web apps and browser/server programming."],["Java","JV","JVM applications, OOP and production patterns."],["C++","C++","Modern C++, algorithms and high-performance software."],["TypeScript","TS","Typed JavaScript and scalable application architecture."],["PHP","PH","Server-side web apps, HTTP and secure data access."],["Kotlin","KT","Null safety, coroutines and Android foundations."],["C","C","C language fundamentals, memory, compilation and systems programming."],["C#","C#","Modern .NET, async code and application development."],["Rust","RS","Ownership, borrowing and reliable systems programming."],["Swift","SW","Swift language and Apple-platform foundations."],["React","RE","Components, state and accessible UI architecture."],["SQL","SQ","Relational modelling, queries, joins and transactions."],["R","R","Statistics, data wrangling and reproducible analysis."],["Go (Golang)","GO","Concurrent services, tooling and production APIs."],["Lua","LU","General-purpose embeddable scripting, tables and metatables."],["Roblox Lua (Luau)","RB","Roblox Studio, events, replication and secure multiplayer systems."]];
const STAGES=[
["1 · Foundations","Output, values, variables and expressions","Beginner"],
["2 · Control flow","Conditions and tracing decisions","Beginner"],
["3 · Functions","Parameters, return values and reuse","Beginner"],
["4 · Collections","Store and process related values","Beginner"],
["5 · Debug & test","Fix mistakes and test a small program","Beginner"]];
const QUIZ=[
{q:"A program behaves unexpectedly. What is the strongest first step?",a:["Rewrite everything","Reproduce a small failing case","Add random delays","Ignore it if it works once"],c:1,w:"A minimal reproducible case helps isolate the cause and can become a regression test."},
{q:"What is a function's return value?",a:["Always the text printed","A value the caller can receive","A comment","The number of lines"],c:1,w:"Returning a value and printing are different operations."},
{q:"Why test boundary cases?",a:["To slow the program","They replace documentation","Bugs often hide at empty, maximum or just-invalid inputs","They prove there are no bugs"],c:2,w:"Boundary tests challenge assumptions. Tests reduce risk but cannot prove software bug-free."},
{q:"Which practice helps prevent SQL injection?",a:["Concatenate input into SQL","Use parameterized queries","Hide the form","Trust all signed-in users"],c:1,w:"Parameters separate data from query syntax; validate inputs too."},
{q:"What does Big-O describe?",a:["Exact runtime on every computer","How resource use scales as input grows","Variable-name quality","Language age"],c:1,w:"Big-O describes growth, not exact wall-clock time."}];
const PROJECTS=[
["CLI Habit Tracker","Python / Go / Java","Build a tested command-line app with persistent storage and validation.",["Command parsing","Persistence","Unit tests and edge cases","README and release notes"]],
["Accessible Portfolio","HTML / CSS / JavaScript","Build a responsive portfolio with semantic markup and keyboard navigation.",["Responsive layout","Accessibility checks","Form validation","Performance and deployment"]],
["Typed Task API","TypeScript / PHP / Java / C#","Design a data-backed API with validation, structured errors and tests.",["API contract","SQL schema and safe queries","Error handling","Automated tests"]],
["Data Exploration Report","R / Python / SQL","Turn a dataset into reproducible analysis with honest conclusions.",["Data-quality checks","Exploration","Visualisation","Reproducible report"]],
["Systems Utility","Rust / C++ / Swift / Kotlin","Build a reliable utility and document resource and error handling.",["Input validation","Core algorithm","Benchmark and test","Design decisions"]],
["Roblox Round Game","Roblox Lua (Luau)","Build a multiplayer round loop with server-authoritative game logic.",["Round state machine","Validate RemoteEvents","Server-side rewards","Exploit-minded tests"]]];
const KEY=(l,i)=>l+"::"+i, $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const defaults={name:"Apprentice",xp:0,completed:{},goals:[{id:1,title:"Study consistently",detail:"Complete one focused learning session",done:false}],streak:0,lastStudy:"",minutes:0,selected:"Python",quizRuns:0,quizCorrect:0,quizBest:0,projectSeen:false,dailyTarget:10,dailyMinutes:0,dailyDate:"",failedAttempts:{},lastLesson:""};
let state;try{const stored=JSON.parse(window.localStorage.getItem("codequest-state")||"{}");state={...defaults,...(stored&&typeof stored==="object"?stored:{})};if(!state.completed||typeof state.completed!=="object"||Array.isArray(state.completed))state.completed={};if(!Array.isArray(state.goals))state.goals=[...defaults.goals];state.xp=Math.max(0,Number(state.xp)||0);state.minutes=Math.max(0,Number(state.minutes)||0);state.streak=Math.max(0,Number(state.streak)||0);if(state.selected==="C+")state.selected="C";if(!LANGS.some(x=>x[0]===state.selected))state.selected="Python"}catch{state={...defaults,completed:{},goals:[...defaults.goals]}}
let view="dashboard",lang=state.selected||"Python",moduleIndex=0,quizAnswers={},quizSubmitted=false;
let cloudClient=null,cloudUser=null,cloudLeaderboard=[],cloudStatus="Not connected";
function save(){try{window.localStorage.setItem("codequest-state",JSON.stringify(state))}catch(e){console.warn("Could not save local progress",e)}topbar();if(cloudClient&&cloudUser)syncCloudProgress().catch(e=>console.warn("Cloud sync failed",e))}
async function syncCloudProgress(){if(!cloudClient||!cloudUser)return;let a=await cloudClient.from("user_progress").upsert({user_id:cloudUser.id,state,updated_at:new Date().toISOString()},{onConflict:"user_id"});if(a.error)throw a.error;let p=await cloudClient.from("profiles").upsert({user_id:cloudUser.id,display_name:String(state.name||"Learner").slice(0,35),xp:Number(state.xp)||0,level:level(),rank:rank(),streak:Number(state.streak)||0,lessons_completed:allDone(),updated_at:new Date().toISOString()},{onConflict:"user_id"});if(p.error)throw p.error}
async function loadCloudProgress(){if(!cloudClient||!cloudUser)return;const r=await cloudClient.from("user_progress").select("state").eq("user_id",cloudUser.id).maybeSingle();if(r.error)throw r.error;if(r.data?.state){const x=r.data.state;state={...state,...x,completed:{...(state.completed||{}),...(x.completed||{})},failedAttempts:{...(state.failedAttempts||{}),...(x.failedAttempts||{})}};state.xp=Math.max(Number(state.xp)||0,Number(x.xp)||0);state.minutes=Math.max(Number(state.minutes)||0,Number(x.minutes)||0);try{localStorage.setItem("codequest-state",JSON.stringify(state))}catch{}}}
async function connectCloud(){const c=window.CODEQUEST_AUTH_CONFIG||{};if(!c.supabaseUrl||!c.supabaseAnonKey||!window.supabase?.createClient)return false;cloudClient=window.supabase.createClient(c.supabaseUrl,c.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const s=await cloudClient.auth.getSession();cloudUser=s.data.session?.user||null;if(cloudUser)await loadCloudProgress();cloudClient.auth.onAuthStateChange((event,session)=>{cloudUser=session?.user||null;cloudStatus=cloudUser?"Signed in as "+(cloudUser.email||"Google account"):"Signed out";const accountButton=$("#accountBtn");if(accountButton)accountButton.textContent=cloudUser?"Sign out · "+(cloudUser.email||"Account"):"Sign in with Google";if(cloudUser)setTimeout(()=>loadCloudProgress().then(()=>{render();syncCloudProgress().catch(console.warn)}).catch(console.warn),0);else render()});return true}
function accountAction(){if(!cloudClient){modal("Connect your free account",'<p>Google sign-in and cross-device sync require a free Supabase project. Follow <a href="SETUP.md" target="_blank" rel="noopener">SETUP.md</a>, run <code>supabase/schema.sql</code>, enable Google OAuth, and fill <code>auth-config.js</code>.</p><p class="muted small">Never put a service-role key in the public repository.</p><div class="actions"><button class="btn primary" id="closeAccountSetup">Close</button><a class="btn" href="https://supabase.com/dashboard" target="_blank" rel="noopener">Open Supabase</a></div>');$("#closeAccountSetup").onclick=()=>$("#modal").innerHTML="";return}if(cloudUser){cloudClient.auth.signOut().then(()=>toast("Signed out."));return}cloudClient.auth.signInWithOAuth({provider:"google",options:{redirectTo:window.CODEQUEST_AUTH_CONFIG.redirectTo||location.href}}).then(({error})=>{if(error)toast("Sign-in failed: "+error.message)}).catch(e=>toast(e.message))}
function cloudHint(){return !cloudClient?'<p class="muted small">Cloud sync is not configured. See SETUP.md.</p>':cloudUser?'<p class="muted small">Signed in · '+safe(cloudUser.email||"Google account")+' · '+safe(cloudStatus)+'</p>':'<p class="muted small">Sign in with Google to sync progress across devices.</p>'}
function leaderboard(){return heading("COMMUNITY","Leaderboard","Learners ranked by recorded XP. This is a community progress board, not a verified skill ranking.")+'<section class="panel">'+cloudHint()+'<div class="actions"><button class="btn" id="refreshLeaderboard">Refresh leaderboard</button></div>'+(cloudLeaderboard.length?'<div class="leader-list">'+cloudLeaderboard.map((p,i)=>'<div class="rowcard"><div class="symbol">#'+(i+1)+'</div><div class="grow"><b>'+safe(p.display_name||"Learner")+'</b><small>'+safe(p.rank||"Novice")+' · Level '+(Number(p.level)||1)+' · '+(Number(p.lessons_completed)||0)+' lessons</small></div><b>'+Number(p.xp||0).toLocaleString()+' XP</b></div>').join("")+'</div>':'<p class="muted">Connect a configured cloud account to load public rankings.</p>')+'</section>'}
async function refreshLeaderboard(){if(!cloudClient)return;const r=await cloudClient.from("profiles").select("display_name,xp,level,rank,lessons_completed,updated_at").order("xp",{ascending:false}).limit(50);if(r.error){toast("Leaderboard error: "+r.error.message);return}cloudLeaderboard=r.data||[];if(view==="leaderboard")render()}
function safe(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function level(){return Math.floor(state.xp/250)+1}function rank(){return level()>=30?"Guild Master":level()>=20?"Architect":level()>=12?"Senior Builder":level()>=7?"Journeyman":level()>=3?"Apprentice II":"Novice"}
function done(l,i){return !!state.completed[KEY(l,i)]}function count(l){return STAGES.filter((_,i)=>done(l,i)).length}function allDone(){return Object.keys(state.completed).length}
function topbar(){const setText=(selector,value)=>{const el=$(selector);if(el)el.textContent=value};setText("#playerName",state.name);setText("#rank","Level "+level()+" · "+rank());setText("#xp",state.xp+" XP");setText("#streak",state.streak);setText("#avatar",(state.name[0]||"A").toUpperCase());setText("#editName",(state.name[0]||"A").toUpperCase());setText("#topRank",rank());setText("#topLevel","LV "+level())}
function heading(k,t,d){return `<div class="eyebrow">${k}</div><h1 class="heading">${t}</h1><p class="sub">${d}</p>`}
function button(label,action,cls="btn",extra=""){return `<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`}
function stats(){return `<div class="stats-grid"><div class="card"><div class="stat-label">Experience</div><div class="stat-value">${state.xp}</div><div class="stat-note">XP earned through practice</div></div><div class="card"><div class="stat-label">Modules mastered</div><div class="stat-value">${allDone()}</div><div class="stat-note">Across ${new Set(Object.keys(state.completed).map(k=>k.split("::")[0])).size} tracks</div></div><div class="card"><div class="stat-label">Quiz accuracy</div><div class="stat-value">${state.quizRuns?Math.round(state.quizCorrect/(state.quizRuns*QUIZ.length)*100):0}%</div><div class="stat-note">Across recorded answers</div></div><div class="card"><div class="stat-label">Study streak</div><div class="stat-value">${state.streak} days</div><div class="stat-note">${state.minutes} self-reported minutes</div></div></div>`}
function trackCard(l){let n=count(l[0]);return `<article class="path-card"><div class="path-top"><div class="symbol">${l[1]}</div><span class="tag">${n}/${STAGES.length} MODULES</span></div><h3>${l[0]}</h3><p>${l[2]}</p><div class="track"><div class="fill" style="width:${n/STAGES.length*100}%"></div></div><button class="btn" data-action="open" data-lang="${safe(l[0])}">${n?"Continue path":"Start path"} →</button></article>`}
function dashboard(){let recent=LANGS.find(l=>l[0]===lang)||LANGS[0];return `<div class="hero"><div class="hero-grid"><div><div class="eyebrow">YOUR NEXT LEVEL STARTS HERE</div><h1>Learn to code.<br>Build real skills.</h1><p>A free, open-source learning RPG built around deliberate practice, prerequisites and projects. Earn XP for mastery—not mindless clicking.</p><div class="actions">${button("Continue learning →","resume","btn primary")}${button("Review a tricky lesson","review-weak","btn")}${button("Explore all paths","view-paths","btn")}</div></div><div class="levelbox"><div class="eyebrow">CURRENT LEVEL</div><div class="level">${level()}</div><b>${rank()}</b><div class="track"><div class="fill" style="width:${state.xp%250/250*100}%"></div></div><div class="small muted">${state.xp%250}/250 XP to next level</div></div></div></div>${stats()}<div class="grid2"><section class="panel"><div class="panel-title"><h3>Pick up where you left off</h3><span class="tag">50 XP / MODULE</span></div><div class="rowcard"><div class="symbol">${recent[1]}</div><div class="grow"><b>${recent[0]}</b><small>${count(recent[0])} of ${STAGES.length} modules mastered · ${safe(recent[2])}</small></div>${button("Open","open","btn",`data-lang="${safe(recent[0])}"`)}</div><p class="muted small">Master each stage before unlocking the next. XP is awarded once per module.</p></section><section class="panel"><div class="panel-title"><h3>Daily practice</h3><span class="tag">YOUR PACE</span></div><p class="muted">Choose a daily target. There is no energy system, daily lesson cap, paid course lock or penalty for missing a day.</p><div class="form"><label class="small" for="dailyTarget">Daily target</label><select id="dailyTarget"><option value="5" ${Number(state.dailyTarget)===5?"selected":""}>5 minutes</option><option value="10" ${Number(state.dailyTarget)===10?"selected":""}>10 minutes</option><option value="15" ${Number(state.dailyTarget)===15?"selected":""}>15 minutes</option></select><input id="minutes" type="number" min="1" max="600" placeholder="Minutes studied"><button class="btn primary" id="record">Record session</button></div><div class="daily-progress"><span>Daily target progress</span><b>${Math.min(100,Math.round((Number(state.dailyMinutes)||0)/Math.max(1,Number(state.dailyTarget)||10)*100))}%</b></div><div class="track"><div class="fill" style="width:${Math.min(100,(state.minutes%Math.max(1,Number(state.dailyTarget)||10))/Math.max(1,Number(state.dailyTarget)||10)*100)}%"></div></div><small class="muted">Self-reported time only. Progress stays in this browser unless you export it.</small></section></div><div class="section-head"><div><h2>Explore learning paths</h2><p>19 tracks, including separate Lua and Roblox Luau paths.</p></div><button class="btn" data-action="view-paths">View all →</button></div><div class="path-grid">${LANGS.slice(0,6).map(trackCard).join("")}</div>`}
function paths(){return heading("CHOOSE YOUR SPECIALIZATION","Learning paths","All paths are visible. Each has an 11-stage roadmap; later stages remain locked until prerequisites are mastered.")+`<div class="searchbar"><input id="pathSearch" placeholder="Search 19 technologies…"><select id="cat"><option value="all">All paths</option><option>Web</option><option>Programming</option><option>Systems</option><option>Data</option><option>Scripting</option></select></div><div class="path-grid" id="pathGrid">${LANGS.map(trackCard).join("")}</div><p class="callout">C+ is not a widely standardized language designation like C or C++. Its curriculum remains a clarification placeholder rather than silently pretending it means C. React is a JavaScript UI library, not a standalone language.</p>`}
function tree(){let l=LANGS.find(x=>x[0]===lang)||LANGS[0];let prereq=[[],[0],[0],[0,1],[1],[2,3],[3,4],[5,6],[7],[7,8],[9],[9,10]];let coords=[[18,16],[39,16],[60,16],[81,16],[18,43],[39,43],[60,43],[81,43],[18,70],[39,70],[60,70],[81,70]];let nodes=STAGES.map((st,i)=>{let d=done(l[0],i),u=i===0||done(l[0],i-1);let [x,y]=coords[i]||[10+i*7,85];return {st,i,d,u,x,y}});let lines=nodes.slice(1).map(n=>{let p=nodes[n.i-1];return '<line x1="'+(p.x+4)+'%" y1="'+(p.y+4)+'%" x2="'+(n.x+4)+'%" y2="'+(n.y+4)+'%" class="skill-link '+(n.u?'link-open':'')+'"/>'}).join('');return heading("YOUR SKILL JOURNEY","Skill tree · "+l[0],"Explore a connected map of skills. Master a node to unlock the next; side quests show what you can build with each skill.")+`<div class="map-toolbar"><label for="treeLanguage">Learning path</label><select id="treeLanguage">${LANGS.map(x=>'<option value="'+safe(x[0])+'" '+(x[0]===lang?'selected':'')+'>'+safe(x[0])+'</option>').join("")}</select><span class="tag">${count(l[0])}/${STAGES.length} MASTERED</span><span class="tag">${Math.round(count(l[0])/STAGES.length*100)}% complete</span></div><div class="skillmap-wrap"><div class="skillmap"><svg class="skill-links" viewBox="0 0 1000 620" preserveAspectRatio="none" aria-hidden="true"><defs><marker id="skillArrow" markerWidth="7" markerHeight="7" refX="5" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#5e9e9a"/></marker></defs>${nodes.slice(1).map(n=>{let p=nodes[n.i-1];return '<path d="M '+(p.x*10+36)+' '+(p.y*6+25)+' L '+(n.x*10+36)+' '+(n.y*6+25)+'" class="skill-link '+(n.u?'link-open':'')+'" marker-end="url(#skillArrow)"/>'}).join("")}<path d="M 440 350 Q 320 270 210 275" class="side-link"/><path d="M 650 445 Q 760 500 820 450" class="side-link"/><path d="M 800 140 Q 880 95 820 70" class="side-link"/></svg>${nodes.map(n=>'<button class="skill-node '+(n.d?'mastered':n.u?'available':'locked')+'" style="left:'+n.x+'%;top:'+n.y+'%" data-action="module" data-index="'+n.i+'" data-lang="'+safe(l[0])+'" '+(n.u?'':'disabled')+'><span class="skill-hex"><span>'+(n.d?'✓':n.u?'✦':'🔒')+'</span></span><b>'+safe(n.st[0])+'</b><small>'+safe(n.st[1])+'</small><em>'+(n.d?'MASTERED':n.u?'+50 XP':'LOCKED')+'</em></button>').join("")}<div class="skill-project" style="left:50%;top:54%"><span>🏆</span><b>Capstone project</b><small>Finish the learning route</small></div><button class="skill-sidequest side-one" data-action="module" data-index="4" data-lang="${safe(l[0])}"><b>✧ Side quest</b><span>Debugging & test lab</span><small>Practice branch · Add to goals</small></button><button class="skill-sidequest side-two" data-action="project" data-index="0"><b>✧ Side quest</b><span>Portfolio project</span><small>Optional branch · Build evidence</small></button><div class="map-legend"><span>✓ Mastered</span><span>✦ Available</span><span>🔒 Locked</span><span>┄ Optional side quest</span></div></div></div><p class="small muted">The graph shows the core prerequisite route and optional project branches. Mastery currently uses reflection checks; real automatic code grading is not available yet.</p>`}

const CORE_LESSONS=[
{title:"Values, variables & output",objective:"Explain how this language represents values, names data, and communicates results.",concept:"Programs transform input values into output. Names should describe intent; types and mutability rules determine which values can be stored and changed.",task:"Create two named values, combine them, and display the result. Change one value and predict the output before running it."},
{title:"Decisions & repetition",objective:"Choose conditions carefully and trace loops without off-by-one errors.",concept:"A condition evaluates to a truth value. Branches select behaviour; loops repeat work. Check boundary values, termination, and whether the loop should include its endpoint.",task:"Write a program that classifies a number as negative, zero, or positive, then prints a short sequence. Test -1, 0, and 1."},
{title:"Functions & contracts",objective:"Break a problem into a reusable function with explicit inputs and outputs.",concept:"A function is a named unit of behaviour. Parameters define inputs, return values communicate results, and local scope limits accidental coupling. Keep one clear responsibility per function.",task:"Write a function that accepts two values and returns a result. Add a normal case, a boundary case, and an invalid-input decision."},
{title:"Collections & data modelling",objective:"Select a collection that matches the data and required operations.",concept:"Sequences preserve order; maps associate keys with values; sets represent uniqueness. Choose a structure based on access patterns, invariants, and how the data changes.",task:"Represent three records, look one up by key, and compute a summary. Explain why your chosen structure fits."},
{title:"Debugging, tests & small project",objective:"Use a reproducible test strategy and explain what your program guarantees.",concept:"Separate expected behaviour from implementation. Test typical, boundary, and invalid inputs. A failing test should be reproducible; fix the cause and retain a regression test.",task:"Build a small validated utility using the previous lessons. Include at least five tests, clear error handling, and a README with setup and limitations."}
];
