function lesson(l,i){
const titles=["Meet print()","Store a value","Make a decision","Write a function","Work with a list"];
const tasks=["Make the program print exactly: Hello, world!","Create a variable named name with the value Ada, then print Hello, Ada.","Set n to -2 and print: negative","Create an add function and display the result of 2 + 3.","Create a collection with 2, 4, 6 and display its average."];
const hints=['Use print("Hello, world!") in Python. Quotes mark the text.','Create name = "Ada" and combine it with the greeting.','Use an if condition that checks whether n is less than zero.','Define add(a, b) to return a + b, then call it with 2 and 3.','Add the values and divide by how many values there are.'];
const concepts=["The print() function displays information. Parentheses hold what you want to show, and quotes mark text. The quotes are code; they do not appear in the output.","Variables give values a name so you can reuse them.","Conditions let a program choose which instruction to follow.","Functions are reusable blocks. Parameters are inputs; return values are results.","Collections hold multiple related values. Check edge cases such as an empty list."];
const starter=(EDITORS[l]||EDITORS["JavaScript"])[i]||EDITORS["JavaScript"][0]; const id="cq-code-editor"; const htmlMode=["HTML","CSS","React"].includes(l); const runtime=RUNTIMES[l]; const roblox=l==="Roblox Lua (Luau)";
const intro=i===0&&l==="Python"?"Hi! I\'m your coding teacher. We\'ll start with one tiny instruction. Python has a function called print(). It shows something on the screen.":tasks[i];
return heading("LESSON "+(i+1)+" OF 5 · "+l.toUpperCase(),titles[i],intro)+
 '<div class="lesson-stack"><section class="panel teacher-panel"><div class="eyebrow">YOUR TEACHER · STEP BY STEP</div><h3>First, let\'s make the computer say hello.</h3><p>'+safe(concepts[i])+(i===0&&l==="Python"?'<p>Read this aloud: print, open parenthesis, quote, Hello comma world exclamation mark, quote, close parenthesis.</p>':'')+'</p><pre class="code-sample"><code>'+safe(starter)+'</code></pre><p class="muted small">Change one small thing, run it again, and notice what changed.</p><details><summary>Show me a hint</summary><p>'+safe(hints[i])+'</p></details></section>'+
 '<section class="panel editor-panel"><div class="panel-title"><div><div class="eyebrow">CODE PLAYGROUND · ABOUT 3–5 MIN</div><h3>'+safe(l)+' · Lesson '+(i+1)+'</h3></div><span class="tag">'+(runtime?"RUN CODE":htmlMode?"LIVE PREVIEW":roblox?"ROBLOX STUDIO":"RUNNER NOT CONFIGURED")+'</span></div><p>'+safe(tasks[i])+'</p><label for="'+id+'">Your code</label><textarea id="'+id+'" class="code-editor" spellcheck="false" autocapitalize="off" autocomplete="off">'+safe(starter)+'</textarea><div class="actions"><button class="btn" id="resetCode">Reset example</button><button class="btn primary" id="runCode">'+(htmlMode?"Preview":roblox?"Check lesson":"Run code")+'</button><button class="btn primary" id="checkCode">Run tests & unlock next lesson</button></div><div id="runnerOutput" class="runner-output" role="status" aria-live="polite">Run your code to see output here.</div><p class="muted small">'+(runtime?"Runs in the browser or through the configured public compiler. Do not enter secrets.":htmlMode?"Uses a sandboxed preview. React requires its own runtime.":roblox?"Roblox game APIs must be tested in Roblox Studio.":"This language runner is not configured yet.")+'</p><div class="coach-box"><div><div class="eyebrow">CODE COACH · FREE</div><h3>Stuck? Let’s debug it together.</h3><p class="muted small">Get contextual help from your code and lesson goal. This helper works without a subscription or AI API key.</p></div><div class="actions"><button class="btn" id="explainCode">Explain my code</button><button class="btn" id="practiceHint">Give me a hint</button></div><div id="coachOutput" class="coach-output" aria-live="polite">Your coach is ready when you are.</div><p id="adaptiveNote" class="muted small">'+(Number((state.failedAttempts||{})[KEY(l,i)]||0)>0?"Review suggested: try changing one thing at a time and rerun your test.":"Practice is unlimited. Mistakes help choose what to review next.")+'</p></div></section>'+
 '<section class="panel"><h3>What to do</h3><ol><li>Read the task.</li><li>Write the code yourself.</li><li>Run it and compare the result.</li><li>Fix mistakes and run again.</li></ol><div id="masteryStatus" class="callout">Pass the code test to unlock the next lesson. Retry as often as you need.</div><div class="actions"><button class="btn" data-action="back-tree">Back to skill tree</button><button class="btn primary" id="complete" disabled>Pass tests to master · +50 XP</button></div></section></div>';
}
function goals(){return heading("SMALL STEPS ADD UP","Goals & habits","Set goals that fit your life. Progress is private to this browser; no streak pressure or penalty for taking a break.")+`<section class="panel"><h3>Create a goal</h3><form class="form" id="goalForm"><input id="goalTitle" maxlength="100" required placeholder="e.g. Practise Python functions"><input id="goalDetail" maxlength="180" placeholder="Optional next action"><button class="btn primary">Add goal</button></form></section><div class="section-head"><div><h2>Your goals</h2><p>Check off completed goals or remove ones that no longer help.</p></div></div><div class="goal-list">${state.goals.map(g=>`<div class="goal-card"><input type="checkbox" data-action="toggle-goal" data-id="${g.id}" ${g.done?"checked":""} aria-label="Complete goal"><div class="grow"><b>${safe(g.title)}</b><p>${safe(g.detail||"No extra details")}</p></div><button class="btn" data-action="delete-goal" data-id="${g.id}">Remove</button></div>`).join("")||'<p class="empty">No goals yet. Add one small next step.</p>'}</div>`}
function quiz(){return heading("RETRIEVAL PRACTICE","Quizzes & tests","A short cross-language diagnostic focused on debugging, functions, testing, security and algorithmic thinking. Read explanations after answering.")+`<section class="panel" id="quizPanel"><div class="panel-title"><h3>Developer foundations · 5 questions</h3><span class="tag">BEST ${state.quizBest}/${QUIZ.length}</span></div>${QUIZ.map((q,i)=>`<div class="quiz-question"><b>${i+1}. ${q.q}</b>${q.a.map((a,j)=>`<label class="option"><input type="radio" name="q${i}" value="${j}"> ${a}</label>`).join("")}<div id="feedback${i}"></div></div>`).join("")}<button class="btn primary" id="submitQuiz">Submit answers</button></section>`}
function projects(){return heading("BUILD EVIDENCE, NOT JUST BADGES","Project lab","Portfolio projects are where concepts become evidence. Define acceptance criteria, test edge cases, document decisions and explain your own contribution.")+`<div class="project-grid">${PROJECTS.map((p,i)=>`<article class="project"><div class="path-top"><div class="symbol">0${i+1}</div><span class="tag">${i<2?"FOUNDATION":i<4?"INTERMEDIATE":"ADVANCED"}</span></div><h3>${p[0]}</h3><p>${p[2]}</p><div class="small muted">Suggested stack: ${p[1]}</div><hr style="border-color:var(--line)"><b class="small">Definition of done</b><ul class="small muted">${p[3].map(x=>`<li>${x}</li>`).join("")}</ul><button class="btn" data-action="project" data-index="${i}">View brief →</button></article>`).join("")}</div>`}
function statsView(){return heading("YOUR PERSONAL RECORD","Statistics & backup","Review your own learning history and export a portable JSON backup. Data is not uploaded to a server.")+stats()+`<section class="panel"><h3>Path progress</h3>${LANGS.filter(l=>count(l[0])).map(l=>`<div class="rowcard"><div class="grow"><b>${l[0]}</b><div class="track"><div class="fill" style="width:${count(l[0])/STAGES.length*100}%"></div></div></div><span class="small">${count(l[0])}/${STAGES.length}</span></div>`).join("")||'<p class="empty">No mastered modules yet. Pick a path to begin.</p>'}<hr style="border-color:var(--line)"><div class="actions"><button class="btn" id="export">Export progress JSON</button><button class="btn" id="import">Import progress JSON</button><input id="file" type="file" accept="application/json" hidden></div><button class="btn" id="reset" style="margin-top:10px">Reset local progress…</button><p class="small muted">Export a backup before switching browsers. Reset permanently clears this browser's CodeQuest progress.</p></section>`}
function achievements(){let a=[["First quest","Master one module","✦",allDone()>=1],["Consistent learner","Master five modules","♨",allDone()>=5],["Explorer","Try three tracks","✣",new Set(Object.keys(state.completed).map(k=>k.split("::")[0])).size>=3],["Quiz starter","Submit a diagnostic","◈",state.quizRuns>0],["500 XP","Earn 500 experience","⚡",state.xp>=500],["Builder","Reach level 5","⚙",level()>=5],["Goal setter","Create three goals","◎",state.goals.length>=3],["Project thinker","Open a project brief","▣",state.projectSeen]];return heading("MILESTONES","Achievements & certificates","Earn milestones by learning, practising and building. Certificates are printable local records, not externally verified credentials.")+`<div class="badge-grid">${a.map(x=>`<div class="badge ${x[3]?"earned":""}"><div class="emoji">${x[2]}</div><b>${x[0]}</b><small>${x[1]}</small><small>${x[3]?"✓ UNLOCKED":"◇ LOCKED"}</small></div>`).join("")}</div><section class="panel certificate-panel"><h2>Course certificates</h2><p class="muted">Complete all five lessons in a path to unlock a printable certificate. Save it as a PDF from your browser’s print dialog.</p><div class="certificate-list">${LANGS.map(l=>`<div class="rowcard"><div class="symbol">${l[1]}</div><div class="grow"><b>${safe(l[0])}</b><small>${count(l[0])}/5 lessons completed</small></div><button class="btn ${count(l[0])===5?"primary":""}" data-action="certificate" data-lang="${safe(l[0])}" ${count(l[0])===5?"":"disabled"}>${count(l[0])===5?"Create certificate":"Locked"}</button></div>`).join("")}</div></section>`}
function render(){try{const views={dashboard,paths,tree,goals,quiz,projects,stats:statsView,achievements,leaderboard,lesson:()=>lesson(lang,moduleIndex)};if(!views[view])view="dashboard";$$(".nav[data-view]").forEach(b=>b.classList.toggle("active",b.dataset.view===view));topbar();$("#crumb").textContent=({dashboard:"Dashboard",paths:"Learning paths",tree:"Skill tree",goals:"Goals & habits",quiz:"Quizzes & tests",projects:"Project lab",stats:"Statistics",achievements:"Achievements",leaderboard:"Leaderboard",lesson:"Lesson"})[view]||view;$("#content").innerHTML=views[view]();wire()}catch(error){console.error("CodeQuest render failed",error);$("#content").innerHTML='<section class="panel error-panel"><div class="eyebrow">RECOVERABLE APP ERROR</div><h1 class="heading">This view could not load</h1><p class="sub">Your saved progress has not intentionally been cleared. Return to dashboard or reload. Report repeat errors on GitHub.</p><pre>'+safe(error&&error.message||String(error))+'</pre><button class="btn primary" id="recoverDashboard">Return to dashboard</button><button class="btn" id="reloadApp">Reload app</button></section>';$("#recoverDashboard").onclick=()=>{view="dashboard";render()};$("#reloadApp").onclick=()=>location.reload()}}
