async function coachExplain(hintOnly){
 const editor=$("#cq-code-editor"),box=$("#coachOutput");if(!editor||!box)return;
 const source=editor.value.trim(),name=lang,i=moduleIndex;
 const hints=['Print the exact text Hello, world! Use quotes for text and parentheses around the value.','Create a variable named name with the value Ada, then print a greeting that includes that value.','Set n to -2 and use a condition that checks whether n is less than zero.','Define add(a, b) so it returns a + b, then print the result of add(2, 3).','Use the values 2, 4, and 6. Add them and divide by the number of values to get 4.'];
 const errors=[];if(!source)errors.push("The editor is empty. Start with the example, then change one small part.");
 if(name==="Python"&&i===0&&!/print\s*\(/.test(source))errors.push("Python uses print(...) to display output. Check spelling and parentheses.");
 if(name==="Python"&&i===1&&!/\bname\b/.test(source))errors.push("The task asks for a variable called name. Variable names must match exactly.");
 if(name==="Python"&&i===2&&!/if\s+/.test(source))errors.push("This task needs an if statement. Conditions select which branch runs.");
 if(name==="Python"&&i===3&&!/def\s+add\s*\(/.test(source))errors.push("Define the function using def add(a, b): and return a + b.");
 if(name==="Python"&&i===4&&!/\[|sum\s*\(/.test(source))errors.push("Try a list such as [2, 4, 6], then use sum(values) / len(values).");
 if(hintOnly){box.textContent="Hint: "+(hints[i]||"Compare your code with the task and test one small change at a time.");return;}
 if(cloudClient&&cloudUser){box.textContent="Asking the AI mentor…";try{const r=await cloudClient.functions.invoke("ai-mentor",{body:{language:name,lessonIndex:i,code:source,errors}});if(r.error)throw r.error;box.textContent=r.data?.reply||"No tutor response returned.";return}catch(e){box.textContent="AI mentor unavailable: "+(e.message||e)+"\\nOffline hint: "+(hints[i]||"Change one thing and run again.");return}}
 box.textContent=errors.length?"Let's focus on the next step. "+errors.join(" "):"Offline Code Coach: lesson-specific hints. Configure the optional AI mentor in SETUP.md for natural-language explanations. "+(hints[i]||"Try one small change and run it again.");
}
